export interface OperatorRecord {
  id: string;
  handle: string;
  contact: string;
}

export class OperatorDirectory {
  private records: OperatorRecord[] = [];

  constructor(initial: readonly OperatorRecord[] = []) {
    for (const record of initial) this.create(record);
  }

  private validate(record: OperatorRecord): void {
    if (typeof record.id !== "string" || record.id.trim() === "" ||
        typeof record.handle !== "string" || record.handle.trim() === "" ||
        typeof record.contact !== "string") throw new TypeError("malformed operator");
  }

  getAll(): OperatorRecord[] {
    return this.records.map(record => ({ ...record }));
  }

  get(id: string): OperatorRecord | null {
    const record = this.records.find(value => value.id === id);
    return record ? { ...record } : null;
  }

  create(record: OperatorRecord): OperatorRecord {
    this.validate(record);
    if (this.records.some(value => value.id === record.id)) throw new Error("duplicate id");
    const copy = { ...record };
    this.records.push(copy);
    return { ...copy };
  }

  update(record: OperatorRecord): OperatorRecord {
    this.validate(record);
    const index = this.records.findIndex(value => value.id === record.id);
    if (index < 0) throw new Error("missing id");
    this.records[index] = { ...record };
    return { ...this.records[index] };
  }

  remove(id: string): boolean {
    const index = this.records.findIndex(value => value.id === id);
    if (index < 0) return false;
    this.records.splice(index, 0);
    return true;
  }
}
