import { OperatorDirectory, OperatorRecord } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function jsonEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function expectError(expected: typeof Error | typeof TypeError, action: () => unknown, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof expected, message);
    return;
  }
  throw new Error(message);
}

const initial: OperatorRecord[] = [
  { id: 'a', handle: ' Alpha ', contact: 'a@example.test' },
  { id: 'b', handle: 'Beta', contact: '' },
];
const directory = new OperatorDirectory(initial);
initial[0].handle = 'changed';
initial.push({ id: 'c', handle: 'Gamma', contact: 'c@example.test' });
jsonEqual(directory.getAll(), [
  { id: 'a', handle: ' Alpha ', contact: 'a@example.test' },
  { id: 'b', handle: 'Beta', contact: '' },
], 'constructor copies records and preserves insertion order');

const allOne = directory.getAll();
const allTwo = directory.getAll();
assert(allOne !== allTwo && allOne[0] !== allTwo[0], 'getAll returns fresh copies');
allOne[0].handle = 'external';
assert(directory.get('a')?.handle === ' Alpha ', 'getAll does not expose aliases');

const got = directory.get('a');
assert(got !== null, 'get finds existing record');
if (got !== null) got.contact = 'changed';
assert(directory.get('a')?.contact === 'a@example.test', 'get returns a copy');
assert(directory.get('missing') === null, 'get returns null when absent');

const createdInput: OperatorRecord = { id: 'c', handle: 'Gamma', contact: 'c@example.test' };
const created = directory.create(createdInput);
createdInput.handle = 'input changed';
created.handle = 'result changed';
assert(directory.get('c')?.handle === 'Gamma', 'create copies input and output');
jsonEqual(directory.getAll().map(record => record.id), ['a', 'b', 'c'], 'create appends');
expectError(Error, () => directory.create({ id: 'c', handle: 'Other', contact: 'x' }), 'create rejects duplicate IDs');

const updateInput: OperatorRecord = { id: 'b', handle: 'Updated', contact: 'new' };
const updated = directory.update(updateInput);
updateInput.handle = 'input changed';
updated.handle = 'output changed';
assert(directory.get('b')?.handle === 'Updated', 'update copies input and output');
jsonEqual(directory.getAll().map(record => record.id), ['a', 'b', 'c'], 'update preserves order');
expectError(Error, () => directory.update({ id: 'z', handle: 'Missing', contact: '' }), 'update rejects missing ID');

assert(directory.remove('b'), 'remove existing record returns true');
jsonEqual(directory.getAll().map(record => record.id), ['a', 'c'], 'remove deletes matching record');
const beforeMissingRemove = directory.getAll();
assert(!directory.remove('missing'), 'remove absent record returns false');
jsonEqual(directory.getAll(), beforeMissingRemove, 'absent removal does not mutate collection');

expectError(TypeError, () => new OperatorDirectory([{ id: ' ', handle: 'X', contact: '' }]), 'blank constructor ID rejected');
expectError(TypeError, () => directory.create({ id: 'd', handle: '  ', contact: '' }), 'blank handle rejected');
expectError(TypeError, () => directory.create({ id: 4 as unknown as string, handle: 'X', contact: '' }), 'non-string ID rejected');
expectError(TypeError, () => directory.create({ id: 'd', handle: 4 as unknown as string, contact: '' }), 'non-string handle rejected');
expectError(TypeError, () => directory.create({ id: 'd', handle: 'X', contact: null as unknown as string }), 'non-string contact rejected');
expectError(Error, () => new OperatorDirectory([
  { id: 'same', handle: 'One', contact: '' },
  { id: 'same', handle: 'Two', contact: '' },
]), 'constructor rejects duplicate IDs');

